import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from './Navbar';

const Profile = () => {
  const [user, setUser] = useState(null);
  const [myPosts, setMyPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newPost, setNewPost] = useState({
    caption: '',
    image: null, // Changed from '' to null for file
    area: ''
  });
  const [imagePreview, setImagePreview] = useState(null);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    fetchUserData();
    fetchMyPosts();
  }, []);

  const fetchUserData = async () => {
    try {
      // First, get user from localStorage as fallback
      const localUser = JSON.parse(localStorage.getItem('user') || '{}');
      setUser(localUser);
      
      // Then fetch fresh data from backend if we have a token
      const token = localStorage.getItem('token');
      if (token) {
        const response = await axios.get('http://localhost:5000/api/auth/me', {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        
        if (response.data.success) {
          setUser(response.data.user);
          // Update localStorage with fresh data
          localStorage.setItem('user', JSON.stringify(response.data.user));
        }
      }
    } catch (err) {
      console.error('Fetch user data error:', err);
      // If API fails, keep using localStorage data
    }
  };

  const fetchMyPosts = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const localUser = JSON.parse(localStorage.getItem('user') || '{}');
      
      const response = await axios.get('http://localhost:5000/api/posts', {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      if (response.data.success) {
        // Filter posts by current user
        const userPosts = response.data.posts.filter(
          post => post.author._id === localUser._id
        );
        setMyPosts(userPosts);
      }
    } catch (err) {
      console.error('Fetch posts error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    
    if (!newPost.caption || !newPost.image || !newPost.area) {
      alert('Please fill in all fields');
      return;
    }

    setCreating(true);
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:5000/api/posts',
        newPost,
        {
          headers: { 'Authorization': `Bearer ${token}` }
        }
      );

      if (response.data.success) {
        alert(`Post created successfully! ${response.data.notificationsSent} users notified.`);
        setShowCreateModal(false);
        setNewPost({ caption: '', image: '', area: '' });
        fetchMyPosts(); // Refresh posts
      }
    } catch (err) {
      console.error('Create post error:', err);
      alert(err.response?.data?.message || 'Failed to create post');
    } finally {
      setCreating(false);
    }
  };

  const calculateAuthenticity = (post) => {
    const totalVotes = (post.verifications?.length || 0) + (post.refutations?.length || 0);
    return totalVotes > 0 
      ? Math.round((post.verifications?.length || 0) / totalVotes * 100) 
      : 50;
  };

  const getRoleBadgeColor = (role) => {
    const roleLower = role?.toLowerCase();
    switch(roleLower) {
      case 'police': return 'bg-blue-100 text-blue-800 border-blue-300';
      case 'dc': return 'bg-purple-100 text-purple-800 border-purple-300';
      default: return 'bg-green-100 text-green-800 border-green-300';
    }
  };

  // Show loading if user data is not yet available
  if (!user) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-gray-100">
        <Navbar />
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-600 mx-auto"></div>
            <p className="mt-6 text-gray-600 text-lg font-medium">Loading profile...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-gray-100">
      <Navbar />
      
      <div className="max-w-6xl mx-auto px-4 py-8">
        {/* Profile Header - Modern Card Design */}
        <div className="bg-gradient-to-r from-blue-600 to-blue-800 rounded-2xl shadow-2xl overflow-hidden mb-8">
          <div className="relative">
            {/* Decorative Background Pattern */}
            <div className="absolute inset-0 bg-black opacity-10">
              <div className="absolute inset-0" style={{
                backgroundImage: 'radial-gradient(circle at 2px 2px, rgba(255,255,255,0.15) 1px, transparent 0)',
                backgroundSize: '32px 32px'
              }}></div>
            </div>
            
            <div className="relative p-8">
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6">
                {/* Profile Info */}
                <div className="flex items-start gap-6">
                  {/* Avatar */}
                  <div className="flex-shrink-0">
                    <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center shadow-lg ring-4 ring-blue-300">
                      <span className="text-4xl font-bold text-blue-600">
                        {user.fullName?.charAt(0)?.toUpperCase() || 'U'}
                      </span>
                    </div>
                  </div>
                  
                  {/* User Details */}
                  <div className="flex-1">
                    <h1 className="text-3xl md:text-4xl font-bold text-white mb-2">
                      {user.fullName || 'User Profile'}
                    </h1>
                    <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-semibold border-2 ${getRoleBadgeColor(user.role)} mb-4`}>
                      <span className="mr-1">
                        {user.role === 'police' ? '👮' : user.role === 'dc' ? '⚖️' : '👤'}
                      </span>
                      {user.role?.toUpperCase() || 'USER'}
                    </div>
                    
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-white">
                      <div className="flex items-center gap-2 bg-white bg-opacity-20 rounded-lg px-3 py-2 backdrop-blur-sm">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                        </svg>
                        <span className="text-sm truncate">{user.email}</span>
                      </div>
                      
                      <div className="flex items-center gap-2 bg-white bg-opacity-20 rounded-lg px-3 py-2 backdrop-blur-sm">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
                        </svg>
                        <span className="text-sm">{user.phoneNumber}</span>
                      </div>
                      
                      <div className="flex items-center gap-2 bg-white bg-opacity-20 rounded-lg px-3 py-2 backdrop-blur-sm">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                        </svg>
                        <span className="text-sm">{user.district}, {user.upazila}</span>
                      </div>
                      
                      <div className="flex items-center gap-2 bg-white bg-opacity-20 rounded-lg px-3 py-2 backdrop-blur-sm">
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V8a2 2 0 00-2-2h-5m-4 0V5a2 2 0 114 0v1m-4 0a2 2 0 104 0m-5 8a2 2 0 100-4 2 2 0 000 4zm0 0c1.306 0 2.417.835 2.83 2M9 14a3.001 3.001 0 00-2.83 2M15 11h3m-3 4h2" />
                        </svg>
                        <span className="text-sm">NID: {user.nidNumber}</span>
                      </div>
                    </div>
                  </div>
                </div>
                
                {/* Create Post Button */}
                <div className="md:self-start">
                  <button
                    onClick={() => setShowCreateModal(true)}
                    className="group relative bg-white text-blue-600 hover:bg-blue-50 font-bold py-4 px-8 rounded-xl transition-all duration-300 shadow-xl hover:shadow-2xl hover:scale-105 flex items-center gap-2"
                  >
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                    </svg>
                    <span>Create Post</span>
                  </button>
                </div>
              </div>
              
              {/* Address Bar */}
              <div className="mt-6 bg-white bg-opacity-20 backdrop-blur-sm rounded-lg px-4 py-3 text-white">
                <div className="flex items-center gap-2">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
                  </svg>
                  <span className="text-sm font-medium">{user.address}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white rounded-xl shadow-lg p-6 border-t-4 border-blue-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm font-medium uppercase tracking-wide">Total Posts</p>
                <p className="text-4xl font-bold text-gray-900 mt-2">{myPosts.length}</p>
              </div>
              <div className="bg-blue-100 rounded-full p-4">
                <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
            </div>
          </div>
          
          <div className="bg-white rounded-xl shadow-lg p-6 border-t-4 border-green-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm font-medium uppercase tracking-wide">Verifications</p>
                <p className="text-4xl font-bold text-gray-900 mt-2">
                  {myPosts.reduce((sum, post) => sum + (post.verifications?.length || 0), 0)}
                </p>
              </div>
              <div className="bg-green-100 rounded-full p-4">
                <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
            </div>
          </div>
          
          <div className="bg-white rounded-xl shadow-lg p-6 border-t-4 border-red-500 hover:shadow-xl transition-shadow">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm font-medium uppercase tracking-wide">Refutations</p>
                <p className="text-4xl font-bold text-gray-900 mt-2">
                  {myPosts.reduce((sum, post) => sum + (post.refutations?.length || 0), 0)}
                </p>
              </div>
              <div className="bg-red-100 rounded-full p-4">
                <svg className="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
            </div>
          </div>
        </div>

        {/* My Posts Section */}
        <div className="bg-white rounded-2xl shadow-xl p-8">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
              My Posts
            </h2>
            <span className="bg-blue-100 text-blue-800 font-bold px-4 py-2 rounded-full text-lg">
              {myPosts.length}
            </span>
          </div>

          {loading ? (
            <div className="text-center py-16">
              <div className="inline-block">
                <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-600"></div>
              </div>
              <p className="mt-6 text-gray-600 text-lg font-medium">Loading your posts...</p>
            </div>
          ) : myPosts.length === 0 ? (
            <div className="text-center py-16 bg-gray-50 rounded-xl">
              <div className="mb-6">
                <svg className="w-24 h-24 text-gray-300 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <p className="text-gray-600 text-xl font-semibold mb-2">No posts yet</p>
              <p className="text-gray-500 mb-6">Start sharing incidents with your community</p>
              <button
                onClick={() => setShowCreateModal(true)}
                className="bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 text-white font-bold py-3 px-8 rounded-xl transition-all duration-300 shadow-lg hover:shadow-xl inline-flex items-center gap-2"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                Create Your First Post
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              {myPosts.map(post => {
                const authenticity = calculateAuthenticity(post);
                const totalVotes = (post.verifications?.length || 0) + (post.refutations?.length || 0);
                
                return (
                  <div 
                    key={post._id} 
                    className="group bg-gradient-to-br from-white to-gray-50 border-2 border-gray-200 rounded-2xl overflow-hidden hover:shadow-2xl hover:border-blue-300 transition-all duration-300"
                  >
                    <div className="flex flex-col md:flex-row gap-6 p-6">
                      {/* Image Section */}
                      {post.image && (
                        <div className="flex-shrink-0 md:w-56">
                          <div className="relative rounded-xl overflow-hidden shadow-lg group-hover:shadow-xl transition-shadow h-56 md:h-full">
                            <img 
                              src={post.image} 
                              alt="Post" 
                              className="w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-300"
                              onError={(e) => {
                                e.target.src = 'https://via.placeholder.com/400x300/e2e8f0/64748b?text=Image+Unavailable';
                              }}
                            />
                            <div className="absolute top-3 right-3 bg-black bg-opacity-60 backdrop-blur-sm text-white px-3 py-1 rounded-full text-xs font-semibold">
                              {new Date(post.createdAt).toLocaleDateString()}
                            </div>
                          </div>
                        </div>
                      )}
                      
                      {/* Content Section */}
                      <div className="flex-1 space-y-4">
                        {/* Caption */}
                        <p className="text-gray-800 font-medium text-lg leading-relaxed">
                          {post.caption}
                        </p>
                        
                        {/* Location Badge */}
                        <div className="flex items-center gap-2">
                          <span className="inline-flex items-center gap-2 bg-blue-100 text-blue-800 px-4 py-2 rounded-lg font-semibold text-sm">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                            </svg>
                            {post.area}
                          </span>
                        </div>
                        
                        {/* Authenticity Bar */}
                        <div className="space-y-2">
                          <div className="flex items-center justify-between text-sm font-semibold">
                            <span className="text-gray-700">Authenticity Score</span>
                            <span className={`text-lg ${authenticity >= 70 ? 'text-green-600' : authenticity >= 40 ? 'text-yellow-600' : 'text-red-600'}`}>
                              {authenticity}%
                            </span>
                          </div>
                          <div className="relative h-6 bg-gray-200 rounded-full overflow-hidden shadow-inner">
                            <div 
                              className="absolute inset-y-0 left-0 bg-gradient-to-r from-green-500 to-green-600 transition-all duration-500"
                              style={{ width: `${authenticity}%` }}
                            ></div>
                            <div 
                              className="absolute inset-y-0 right-0 bg-gradient-to-r from-red-500 to-red-600"
                              style={{ width: `${100 - authenticity}%` }}
                            ></div>
                          </div>
                        </div>
                        
                        {/* Vote Stats */}
                        <div className="grid grid-cols-3 gap-4">
                          <div className="bg-green-50 border-2 border-green-200 rounded-xl p-3 text-center">
                            <div className="text-2xl font-bold text-green-700">
                              {post.verifications?.length || 0}
                            </div>
                            <div className="text-xs font-semibold text-green-600 mt-1 uppercase tracking-wide">
                              Verified
                            </div>
                          </div>
                          
                          <div className="bg-red-50 border-2 border-red-200 rounded-xl p-3 text-center">
                            <div className="text-2xl font-bold text-red-700">
                              {post.refutations?.length || 0}
                            </div>
                            <div className="text-xs font-semibold text-red-600 mt-1 uppercase tracking-wide">
                              Refuted
                            </div>
                          </div>
                          
                          <div className="bg-blue-50 border-2 border-blue-200 rounded-xl p-3 text-center">
                            <div className="text-2xl font-bold text-blue-700">
                              {totalVotes}
                            </div>
                            <div className="text-xs font-semibold text-blue-600 mt-1 uppercase tracking-wide">
                              Total Votes
                            </div>
                          </div>
                        </div>
                        
                        {/* Timestamp */}
                        <div className="flex items-center gap-2 text-sm text-gray-500">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                          </svg>
                          {new Date(post.createdAt).toLocaleString('en-US', {
                            dateStyle: 'medium',
                            timeStyle: 'short'
                          })}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* Create Post Modal - Enhanced */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm flex items-center justify-center p-4 z-50 animate-fadeIn">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full overflow-hidden transform transition-all animate-scaleIn">
            {/* Modal Header */}
            <div className="bg-gradient-to-r from-blue-600 to-blue-800 px-8 py-6">
              <div className="flex items-center justify-between">
                <h2 className="text-3xl font-bold text-white flex items-center gap-3">
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                  Report New Incident
                </h2>
                <button
                  onClick={() => {
                    setShowCreateModal(false);
                    setNewPost({ caption: '', image: '', area: '' });
                  }}
                  className="text-white hover:bg-white hover:bg-opacity-20 rounded-full p-2 transition-colors"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              <p className="text-blue-100 mt-2">Share important incidents with your community</p>
            </div>
            
            {/* Modal Body */}
            <form onSubmit={handleCreatePost} className="p-8 space-y-6">
              {/* Caption Field */}
              <div>
                <label className="block text-gray-800 font-bold mb-2 text-sm uppercase tracking-wide">
                  Incident Description *
                </label>
                <textarea
                  value={newPost.caption}
                  onChange={(e) => setNewPost({ ...newPost, caption: e.target.value })}
                  placeholder="Provide a detailed description of what happened..."
                  className="w-full px-4 py-3 border-2 border-gray-300 rounded-xl focus:ring-4 focus:ring-blue-200 focus:border-blue-500 transition-all resize-none text-gray-700"
                  rows="5"
                  maxLength="500"
                  required
                />
                <div className="flex justify-between items-center mt-2">
                  <p className="text-xs text-gray-500">Be clear and specific about the incident</p>
                  <p className={`text-sm font-semibold ${newPost.caption.length > 450 ? 'text-red-600' : 'text-gray-600'}`}>
                    {newPost.caption.length}/500
                  </p>
                </div>
              </div>

              {/* Image URL Field */}
              <div>
                <label className="block text-gray-800 font-bold mb-2 text-sm uppercase tracking-wide">
                  Evidence Image URL *
                </label>
                <div className="relative">
                  <input
                    type="url"
                    value={newPost.image}
                    onChange={(e) => setNewPost({ ...newPost, image: e.target.value })}
                    placeholder="https://example.com/image.jpg"
                    className="w-full px-4 py-3 pl-12 border-2 border-gray-300 rounded-xl focus:ring-4 focus:ring-blue-200 focus:border-blue-500 transition-all text-gray-700"
                    required
                  />
                  <svg className="w-6 h-6 text-gray-400 absolute left-3 top-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                  </svg>
                </div>
                <p className="text-xs text-gray-500 mt-2">Provide a direct link to an image of the incident</p>
              </div>

              {/* Area Field */}
              <div>
                <label className="block text-gray-800 font-bold mb-2 text-sm uppercase tracking-wide">
                  Incident Location *
                </label>
                <div className="relative">
                  <input
                    type="text"
                    value={newPost.area}
                    onChange={(e) => setNewPost({ ...newPost, area: e.target.value })}
                    placeholder="e.g., Dhanmondi, Gulshan, Banani..."
                    className="w-full px-4 py-3 pl-12 border-2 border-gray-300 rounded-xl focus:ring-4 focus:ring-blue-200 focus:border-blue-500 transition-all text-gray-700"
                    required
                  />
                  <svg className="w-6 h-6 text-gray-400 absolute left-3 top-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                  </svg>
                </div>
                <p className="text-xs text-gray-500 mt-2">
                  <span className="font-semibold">⚠️ Note:</span> All users in this area will receive a notification
                </p>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-4 pt-4">
                <button
                  type="submit"
                  disabled={creating}
                  className="flex-1 bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 disabled:from-gray-400 disabled:to-gray-500 text-white font-bold py-4 px-6 rounded-xl transition-all duration-300 shadow-lg hover:shadow-xl disabled:cursor-not-allowed flex items-center justify-center gap-2"
                >
                  {creating ? (
                    <>
                      <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                      <span>Creating Post...</span>
                    </>
                  ) : (
                    <>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                      </svg>
                      <span>Create Post</span>
                    </>
                  )}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowCreateModal(false);
                    setNewPost({ caption: '', image: '', area: '' });
                  }}
                  disabled={creating}
                  className="flex-1 bg-gray-200 hover:bg-gray-300 disabled:bg-gray-100 text-gray-800 font-bold py-4 px-6 rounded-xl transition-all duration-300 disabled:cursor-not-allowed"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
